<?php include 'includes/header.php';$u=user();if(is_admin())$r=mysqli_query($conn,"SELECT * FROM alerts ORDER BY created_at DESC LIMIT 100");else{$s=mysqli_prepare($conn,"SELECT * FROM alerts WHERE institution_code='' OR (institution_type=? AND institution_code=?) ORDER BY created_at DESC LIMIT 100");mysqli_stmt_bind_param($s,'ss',$u['institution_type'],$u['institution_code']);mysqli_stmt_execute($s);$r=mysqli_stmt_get_result($s);}?>
